#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>x={1,2,4,6};double observed=(x[0]+x[1]-x[2]-x[3])/2;int total=0,extreme=0;for(int i=0;i<4;i++)for(int j=i+1;j<4;j++){double sumA=x[i]+x[j],sumB=0;for(int k=0;k<4;k++)if(k!=i&&k!=j)sumB+=x[k];double delta=(sumA-sumB)/2;total++;if(fabs(delta)>=fabs(observed)-1e-12)extreme++;}cout<<"permutation p "<<double(extreme)/total<<"\n";
return 0;
}

